--
-- Name: validate_home_owner_role(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.validate_home_owner_role() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_role system_user_role;
BEGIN
  IF NEW.owner_user_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT role INTO v_role
  FROM users
  WHERE id = NEW.owner_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Owner user % not found', NEW.owner_user_id;
  END IF;

  IF v_role NOT IN ('CUSTOMER', 'ADMIN', 'SUPER_ADMIN') THEN
    RAISE EXCEPTION 'Home owner must have system role CUSTOMER, ADMIN or SUPER_ADMIN';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.validate_home_owner_role() OWNER TO postgres;

